from author import C,S,R,P,T
c=C('导数与复合函数求导')
S(c,'导数定义：看清增量除法',[R('定义',r"f'(a)=\lim_{h\to0}\frac{f(a+h)-f(a)}h"),R('例题',r"f(x)=x^2,\quad a=1"),R('代入并展开',r"\frac{(1+h)^2-1}{h}=2+h"),R('取极限',r"f'(1)=2")],[P('导数定义先记成可操作的四步：把自变量从a换成a加h，减去原来的函数值，再除以h，最后令h趋于零。题目给的是这个差商极限时，优先识别它对应哪个函数在哪一点的导数。分子两个函数值的顺序、分母的增量，都需要一一对应。',[1,2],['先代a加h，再减f(a)','分母是自变量的增量h']),P('例题函数是x平方，在一处求导。分子展开成二h加h平方，除以h得到二加h，再取极限就是二。若题目把分母写成二h，而分子仍是f的一加h减f的一，整个结果就要再除以二，不能看到相似形状就直接写导数值。',[3,4],['先展开约去h，再取极限','差商前的系数不能忽略'])],['导数的定义'])
S(c,'求导公式与四则运算',[R('幂、指数、对数',r"(x^a)'=ax^{a-1},\quad(e^x)'=e^x,\quad(\ln x)'=\frac1x"),R('三角函数',r"(\sin x)'=\cos x,\quad(\cos x)'=-\sin x"),R('乘法法则',r"(uv)'=u'v+uv'"),R('除法法则',r"\left(\frac{u}{v}\right)'=\frac{u'v-uv'}{v^2}\quad(v\ne0)"),R('反三角函数',r"(\arctan x)'=\frac1{1+x^2},\quad(\arcsin x)'=\frac1{\sqrt{1-x^2}}")],[P('常见求导先背这些公式。x的固定a次方，指数a乘下来，次数减一；e的x次方保持原样；自然对数导数是一除以x。正弦求导得余弦，余弦求导有负号。常数导数为零，和差可以分别求导。这里a是固定常数，若指数也含x，后面要换方法。',[1,2],['常数导数为零','余弦求导别漏负号']),P('乘积不能只把两个导数相乘，要写前导后不导，加前不导后导。商的分母平方，分子按上导下不导，减上不导下导，顺序不能反。反正切和反正弦也常出现，注意反正弦的根号中是减号，反正切的分母是加号，并且原函数的实数定义域仍要满足。',[3,4,5],['乘积两项相加；商的分子有减号','公式应用前检查定义域'])],['导数的定义','复合函数链式法则'])
S(c,'链式法则：由外到内乘起来',[R('模板',r"y=F(u),\ u=g(x)\quad\Longrightarrow\quad y'=F'(u)g'(x)"),R('例题',r"y=\sin(x^2+1)"),R('外层导数乘内层导数',r"y'=\cos(x^2+1)\cdot2x"),R('多层照样逐层处理',r"\left[e^{\sin3x}\right]'=e^{\sin3x}\cos3x\cdot3")],[P('看到函数套函数，用链式法则。先把最外层求导，里面那一整块暂时照抄，再乘里面这一块的导数。正弦x平方加一，外层正弦变余弦，里面仍是x平方加一，最后乘二x。入门时把里面圈成一个u，能明显减少漏乘内层导数的问题。',[1,2,3],['先外层，里面先照抄','最后乘内层的导数']),P('如果有三层，就连续乘三层的导数。最后一个例子先保留指数函数，再乘正弦三x的导数，也就是余弦三x，再乘三。检查答案时从外往内数一遍：原式有几层需要变化，你的式子是否都处理了。别把求完内层之后的新表达式塞回外层，外层参数要保留原来的形状。',[4],['内层系数三也要乘','外层中的参数保留原式'])],['复合函数链式法则'])
S(c,'抽象函数：保留撇号与内部参数',[R('题目',r"y=f(x^2),\quad f'(4)=3"),R('先按链式法则',r"y'=f'(x^2)\cdot2x"),R('再在指定点代入',r"y'(2)=f'(4)\cdot4=12"),R('二次求导仍按乘法与链式',r"y''=4x^2f''(x^2)+2f'(x^2)")],[P('抽象函数就是没有告诉你具体表达式的f，不能擅自把它看成x平方或常数。它求导后先写成f撇，括号内仍保留原来的参数，再乘参数的导数。题目给y等于f括号x平方，先得到f撇括号x平方乘二x。得到这个一般式之后，再代入需要的位置。',[1,2],['不知道f的式子，也能写f撇','括号里的x平方要保留']),P('要求x等于二时的导数，先算内部参数变成四，因此使用题目给的f撇四等于三，再乘四，结果十二。若还求二阶导，对刚才的乘积再求导，得到第一项四x平方乘f两撇，加第二项二倍f撇。这里既用乘法法则，也再次用到了链式法则。',[3,4],['先算内部参数，再查题给信息','求二阶时两条法则一起用'])],['抽象函数求导','高阶导数'])
S(c,'幂指函数：先取自然对数',[R('识别形式',r"y=u(x)^{v(x)},\quad u(x)>0"),R('取对数',r"\ln y=v\ln u"),R('通用结果',r"y'=u^v\left(v'\ln u+v\frac{u'}u\right)"),R('例题',r"(x^x)'=x^x(\ln x+1)\quad(x>0)")],[P('底数含x，指数也含x，这类幂指函数不要硬套固定幂公式。对底数为正的情形，先令y等于原式，两边取自然对数，把指数放到前面。右侧变成一个乘积，用乘法法则；左侧对x求导要写成y撇除以y。这个y撇不能因为y没有明写成x就漏掉。',[1,2],['底数和指数都变时先取对数','对ln y求导是y撇除以y']),P('整理后把y乘回去，就得到屏幕上的通用模板。以x的x次方为例，取对数后是x乘ln x，求导为ln x加一，最终再乘回x的x次方。实数范围按x大于零处理。只要先认清这是幂指函数，后面的步骤就是取对数、求导、乘回原式。',[3,4],['结果别漏乘原函数','x的x次方在这里要求x大于零'])],['幂指函数求导'])
S(c,'求导练习',[R('计算导数',r"y=\ln(1+x^2)")],[P('现在暂停，求自然对数一加x平方的导数。先指出外层是什么，内层是什么，再按由外到内的顺序写答案。最容易出错的是只写一个分式，忘了乘里面的二x。写完以后再检查分母是否保留了完整的一加x平方。',[1],['先找外层，再乘内层导数','答案在下一页'])],['复合函数链式法则'],kind='question')
S(c,'求导练习答案',[R('外层',r"y'=\frac1{1+x^2}\cdot(x^2+1)'"),R('结果',r"y'=\frac{2x}{1+x^2}")],[P('外层自然对数的导数是一除以内层，内层一加x平方的导数是二x，所以结果二x除以一加x平方。这个分母始终为正，原式对所有实数都有定义。如果你写成一除以二x，就是把“对内层取倒数”和“再乘内层导数”混成了一步，回到模板逐项写即可。',[1,2],['正确结果二x除以一加x平方','链式法则是相乘'])],['复合函数链式法则'],kind='answer')

c=C('特殊求导与微分')
S(c,'参数方程：先对参数求导',[R('一阶导数',r"\frac{dy}{dx}=\frac{dy/dt}{dx/dt}\quad(x_t\ne0)"),R('例题',r"x=t^2+1,\quad y=t^3"),R('计算',r"\frac{dy}{dx}=\frac{3t^2}{2t}=\frac{3t}{2}\quad(t\ne0)"),R('二阶导数',r"\frac{d^2y}{dx^2}=\frac{d(dy/dx)/dt}{dx/dt}=\frac3{4t}")],[P('参数方程里x和y都用t表示，不必急着消去t。先分别对t求导，然后用y的导数除以x的导数。例题上面是三t平方，下面是二t，约成三t除以二。这个公式要求x对t的导数不为零，所以当前这一条计算路线要注明t不等于零，不能把约分后的式子随意用于原公式失效的位置。',[1,2,3],['y对t求导，除以x对t求导','先检查分母导数不为零']),P('二阶导数更容易漏一步：把刚才的一阶导数再对t求导以后，还要除以x对t的导数。三t除以二对t求导为二分之三，再除以二t，得到四t分之三。考试中把“再除一次x的参数导数”单独写一行，能防止把对t的导数误当成对x的导数。',[4],['二阶时还要再除一次x_t','结果三除以四t'])],['参数方程求导'])
S(c,'隐函数：含y的项都要带y撇',[R('题目',r"x^2+xy+y^2=3"),R('两边对x求导',r"2x+y+xy'+2yy'=0"),R('集中含y撇的项',r"(x+2y)y'=-(2x+y)"),R('解出',r"y'=-\frac{2x+y}{x+2y}\quad(x+2y\ne0)")],[P('隐函数题不用先解出y。直接把等式两边对x求导，但要记住y也是x的函数。x平方变二x，xy用乘法法则得到y加x乘y撇，y平方得到二y乘y撇，常数三变零。最常见的漏项，一个是xy的第二项，另一个是y平方后面的y撇。',[1,2],['对含y的复合项补上y撇','xy按乘积法则分成两项']),P('把所有含y撇的项移到一侧，提取公因子，再除以系数，得到负的二x加y除以x加二y。若指定在一、一处求导，先验证点满足原方程，再代入得负一。分母系数为零时，不能继续用这个除法式子硬算，需要另外判断题目所要求的位置。',[3,4],['先提取y撇，再解出来','指定点先核对原方程'])],['隐函数求导'])
S(c,'切线与法线：先找点再找斜率',[R('切线方程',r"y-y_0=f'(x_0)(x-x_0)"),R('法线方程',r"y-y_0=-\frac1{f'(x_0)}(x-x_0)\quad(f'(x_0)\ne0)"),R('例题',r"y=x^2,\quad(x_0,y_0)=(1,1),\quad k=2"),R('切线与法线',r"y-1=2(x-1),\quad y-1=-\frac12(x-1)"),R('水平切线的法线',r"f'(x_0)=0\quad\Longrightarrow\quad x=x_0")],[P('切线和法线题固定按两步做。先求出点的完整坐标，再把导数在该点的值算出来作为切线斜率。切线用点斜式，y减点的纵坐标等于斜率乘x减横坐标。题目只给横坐标时，纵坐标要代回原函数求，不能拿导数值代替点的高度。',[1,3],['切点坐标来自原函数','切线斜率来自导数']),P('法线与切线垂直，切线斜率非零时，法线斜率是它的负倒数。x平方在一、一处切线斜率二，法线斜率负二分之一，因此得到第四行。若切线水平，法线就是竖直线x等于横坐标，不能把负一除以零当成一个普通斜率代进公式。',[2,4,5],['非零斜率取负倒数','水平切线对应竖直法线'])],['切线方程、法线方程'])
S(c,'高阶导数：先找可复用规律',[R('指数函数',r"\frac{d^n}{dx^n}e^{kx}=k^n e^{kx}"),R('正弦循环',r"\sin x\to\cos x\to-\sin x\to-\cos x\to\sin x"),R('对数函数',r"\frac{d^n}{dx^n}\ln x=(-1)^{n-1}\frac{(n-1)!}{x^n}\quad(n\ge1,x>0)"),R('例题',r"\frac{d^{2026}}{dx^{2026}}\sin x=-\sin x")],[P('求高阶导数不要把很多次求导机械展开。指数函数e的kx次方，每求一次多乘一个k，所以n阶就是k的n次方乘原函数。正弦和余弦四次一循环，按一阶、二阶、三阶、四阶写小表，再把阶数除以四看余数。这个办法比凭感觉猜负号稳定。',[1,2],['指数每次多乘一次内部常数','三角函数先列四项循环']),P('二零二六除以四余二，因此正弦的二零二六阶导与二阶同形，是负正弦。自然对数的n阶公式也值得记，注意正负号次数是n减一，阶乘也是n减一，分母是x的n次方。多项式则不断降次，非负整数次幂超过原次数以后导数为零，别把这一点推广到任意实数次幂。',[3,4],['ln x公式中两处都是n减一','只有多项式才会在有限次后归零'])],['高阶导数'])
S(c,'多项式乘指数的高阶题',[R('题目',r"y=xe^x"),R('前两阶',r"y'=(x+1)e^x,\quad y''=(x+2)e^x"),R('通用结果',r"y^{(n)}=(x+n)e^x\quad(n\ge1)"),R('写成分配求导的形式',r"y^{(n)}=xe^x+n\cdot1\cdot e^x")],[P('还有一类高阶题是多项式乘指数，比如x乘e的x次方。先求前两阶，得到x加一乘指数，x加二乘指数，通常就能看出规律。写n阶时不要把x变成零后直接宣布整个乘积没了，因为每次还有导数落在指数这一侧的项，乘法法则始终要保留。',[1,2],['先算少量阶数识别形状','乘积不能只让某一个因子求导']),P('这题的n阶结果是x加n，再乘e的x次方。用高阶乘积公式看也很直接：x自己不求导的项是一份，x只求一次的项有n份，求两次以上就为零。遇到x平方乘指数，可以沿同样路线保留到二阶导的三类项。现在先记住这道一阶多项式的模板，并能代入具体阶数。',[3,4],['本题结果是x加n乘原指数','多项式因子决定保留多少类项'])],['高阶导数'])
S(c,'微分：导数后面乘dx',[R('微分公式',r"dy=f'(x)\,dx"),R('例题',r"y=\ln(1+x^2)"),R('结果',r"dy=\frac{2x}{1+x^2}\,dx"),R('近似计算',r"\Delta y\approx f'(x_0)\Delta x")],[P('题目让求微分，先照常求导，然后在后面乘dx。不要只写一个导数表达式就结束，因为dy与y撇的书写对象不同。例题自然对数一加x平方，导数刚算过，是二x除以一加x平方，因此微分就是这个结果乘dx，链式法则的二x同样不能丢。',[1,2,3],['求微分最后必须有dx','内部函数仍按链式法则处理']),P('若题目用微分做近似计算，选一个容易计算、又靠近目标的x零，使用函数值加导数乘小增量。这里写近似号，不是任意增量下都精确相等。比如平方根在四附近，导数是四分之一，所以四点零四的平方根可近似为二加零点零一，即二点零一。',[4],['增量近似时使用近似号','计算点要接近目标且容易代入'])],['微分'])
S(c,'特殊求导练习',[R('方程与指定点',r"x^2+y^2=2,\quad(1,1)"),R('求该点切线',r"y-y_0=k(x-x_0)")],[P('暂停练习：x平方加y平方等于二，在一、一处求切线方程。先确认这个点在曲线上，再隐式求导，代入得到斜率，最后写点斜式。请特别检查对y平方求导以后有没有乘上y撇，答案先不要急着把常数全部移到同一边。',[1,2],['隐式求导后求点处斜率','答案在下一页'])],['隐函数求导','切线方程、法线方程'],kind='question')
S(c,'特殊求导练习答案',[R('求导',r"2x+2yy'=0\quad\Longrightarrow\quad y'=-\frac{x}{y}"),R('代入与点斜式',r"k=-1,\quad y-1=-(x-1)"),R('整理',r"x+y=2")],[P('两边求导得到二x加二y乘y撇等于零，因此y撇等于负x除以y。在一、一处斜率为负一，切线写成y减一等于负的x减一，整理得到x加y等于二。原方程里没有把y单独解出来，并不妨碍我们按固定步骤完成切线计算。',[1,2,3],['切线为x加y等于二','点与斜率两项都已代入'])],['隐函数求导','切线方程、法线方程'],kind='answer')
